retained = {"topic": "mirror/fold", "value": "FOLD", "ts": 1000}
def on_join(now, msg, max_age=500):
    age = now - msg["ts"]
    return ("실행" if age <= max_age else "버림"), age
print(on_join(1200, retained))  # ('실행', 200)
print(on_join(4000, retained))  # ('버림', 3000)

DEFAULTS_V2 = {"temp": 22.0, "humidity": 40}
def read_v2(rec): return {**DEFAULTS_V2, **rec}
def read_v1(rec): return {"temp": rec["temp"]}
print(read_v2({"temp": 23.5}))                  # {'temp': 23.5, 'humidity': 40}
print(read_v1({"temp": 21.0, "humidity": 55}))  # {'temp': 21.0}
read_v1({"humidity": 55})                        # KeyError: 'temp'
